const INDENT: &str = "  ";

pub const GENERATED_HEADER: &str =
    "// Generated by femp. Do not edit: changes are overwritten on the next build.";

pub struct SourceWriter {
    buffer: String,
    depth: usize,
    indent: &'static str,
}

impl Default for SourceWriter {
    fn default() -> Self {
        Self::with_indent(INDENT)
    }
}

impl SourceWriter {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn with_indent(indent: &'static str) -> Self {
        Self {
            buffer: String::new(),
            depth: 0,
            indent,
        }
    }

    pub fn line(&mut self, text: impl AsRef<str>) -> &mut Self {
        let text = text.as_ref();
        if !text.is_empty() {
            self.buffer.push_str(&self.indent.repeat(self.depth));
            self.buffer.push_str(text);
        }
        self.buffer.push('\n');
        self
    }

    pub fn blank(&mut self) -> &mut Self {
        self.line("")
    }

    pub fn block(
        &mut self,
        open: impl AsRef<str>,
        close: impl AsRef<str>,
        body: impl FnOnce(&mut Self),
    ) -> &mut Self {
        self.line(open);
        self.depth += 1;
        body(self);
        self.depth -= 1;
        self.line(close)
    }

    pub fn indented(&mut self, body: impl FnOnce(&mut Self)) -> &mut Self {
        self.depth += 1;
        body(self);
        self.depth -= 1;
        self
    }

    pub fn finish(self) -> String {
        self.buffer
    }
}

pub fn string_literal(text: &str) -> String {
    let mut literal = String::with_capacity(text.len() + 2);
    literal.push('"');
    for c in text.chars() {
        match c {
            '"' => literal.push_str("\\\""),
            '\\' => literal.push_str("\\\\"),
            '\n' => literal.push_str("\\n"),
            c => literal.push(c),
        }
    }
    literal.push('"');
    literal
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn indents_nested_blocks() {
        let mut writer = SourceWriter::new();
        writer.block("export class A {", "}", |w| {
            w.block("run(): void {", "}", |w| {
                w.line("return;");
            });
        });

        assert_eq!(
            writer.finish(),
            "export class A {\n  run(): void {\n    return;\n  }\n}\n"
        );
    }

    #[test]
    fn escapes_string_literals() {
        assert_eq!(string_literal("a\"b\\c"), r#""a\"b\\c""#);
    }
}
